//! Every non-deprecated PyAPI_FUNC / PyAPI_DATA declared in spec/Include (inventory in
//! crates/runtime/src/capi/declared.txt, generated by tools/capi_inventory.sh) must be
//! exported from the python3 executable (extensions resolve the C API from it, D13).

use std::collections::HashSet;
use std::process::Command;

#[test]
fn all_declared_capi_symbols_are_exported() {
    let exe = env!("CARGO_BIN_EXE_python3");
    let out = Command::new("nm").args(["-D", "--defined-only", exe]).output().expect("nm must be available");
    assert!(out.status.success(), "nm failed");
    let exported: HashSet<String> = String::from_utf8_lossy(&out.stdout)
        .lines()
        .filter_map(|l| l.split_whitespace().nth(2).map(|s| s.to_string()))
        .collect();
    let decl = std::fs::read_to_string(concat!(env!("CARGO_MANIFEST_DIR"), "/../runtime/src/capi/declared.txt")).unwrap();
    let mut missing = Vec::new();
    let mut total = 0;
    for line in decl.lines() {
        let mut it = line.split_whitespace();
        let (Some(name), Some(_kind), Some(flags)) = (it.next(), it.next(), it.next()) else { continue };
        if flags.split(',').any(|f| f == "dep") {
            continue;
        }
        total += 1;
        if !exported.contains(name) {
            missing.push(name.to_string());
        }
    }
    assert!(total > 1000, "inventory looks truncated ({} entries)", total);
    assert!(missing.is_empty(), "{} declared C-API symbols are not exported: {:?}", missing.len(), missing);
}
